mapper.select:
SELECT sr.id, sr.code, sr.approve_status AS approveStatus, sr.approve_user_id AS approveUserId, sr.approve_user_name AS approveUserName, sr.approve_time AS approveTime, sr.invalid_status AS invalidStatus, sr.invalid_remark AS invalidRemark, sr.invalid_time AS invalidTime, sr.recipient_date AS recipientDate, sr.usage, sr.warehouse_id AS warehouseId, -- wi.name AS warehouseName, sr.user_id AS userId, sr.user_name AS userName, sr.dept_id AS deptId, sr.pick_org_id AS pickOrgId, sr.pick_org_name AS pickOrgName, sr.usage_scope AS usageScope, sr.use_user_id AS useUserId, sr.use_user_name AS useUserName, sr.remark, sr.is_delivery AS isDelivery, sr.receive_address AS receiveAddress, sr.receiver_name AS receiverName, sr.receive_phone AS receivePhone, sr.source_id AS sourceId, sr.source_code AS sourceCode, sr.source_type AS sourceType, sr.create_time AS createTime, sr.create_user_name AS createUserName, srd.id AS detailId, srd.sku_no AS skuNo, srd.sku_id AS skuId, srd.product_name AS productName, srd.recipient_qty AS recipientQty, srd.delivery_qty AS deliveryQty, CASE WHEN srd.exec_status = 'completeOutstock' THEN 0 ELSE (srd.recipient_qty - srd.delivery_qty) END AS reservedQty, srd.exec_status AS execStatus, srd.remark AS detailRemark FROM sample_recipient sr LEFT JOIN sample_recipient_detail srd ON srd.main_id = sr.id AND sr.is_deleted = false -- LEFT JOIN warehouse_info wi ON sr.warehouse_id = wi.id AND wi.is_deleted = false WHERE ${params.sqlMap.default} AND srd.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sr.create_time DESC, srd.id ASC

SELECT sr.id, sr.code, sr.approve_status AS approveStatus, sr.approve_user_id AS approveUserId, sr.approve_user_name AS approveUserName, sr.approve_time AS approveTime, sr.invalid_status AS invalidStatus, sr.invalid_remark AS invalidRemark, sr.invalid_time AS invalidTime, sr.recipient_date AS recipientDate, sr.usage, sr.warehouse_id AS warehouseId, -- wi.name AS warehouseName, sr.user_id AS userId, sr.user_name AS userName, sr.dept_id AS deptId, sr.pick_org_id AS pickOrgId, sr.pick_org_name AS pickOrgName, sr.usage_scope AS usageScope, sr.use_user_id AS useUserId, sr.use_user_name AS useUserName, sr.remark, sr.is_delivery AS isDelivery, sr.receive_address AS receiveAddress, sr.receiver_name AS receiverName, sr.receive_phone AS receivePhone, sr.source_id AS sourceId, sr.source_code AS sourceCode, sr.source_type AS sourceType, sr.create_time AS createTime, sr.create_user_name AS createUserName, srd.id AS detailId, srd.sku_no AS skuNo, srd.sku_id AS skuId, srd.product_name AS productName, srd.recipient_qty AS recipientQty, srd.delivery_qty AS deliveryQty, CASE WHEN srd.exec_status = 'completeOutstock' THEN 0 ELSE (srd.recipient_qty - srd.delivery_qty) END AS reservedQty, srd.exec_status AS execStatus, srd.remark AS detailRemark FROM sample_recipient sr LEFT JOIN sample_recipient_detail srd ON srd.main_id = sr.id AND sr.is_deleted = false WHERE ${params.sqlMap.default} AND srd.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sr.create_time DESC, srd.id ASC

SELECT approve_status AS tabFlag, count(*) AS count FROM sample_recipient WHERE is_deleted=FALSE
${params.permissionSql}
GROUP BY approve_status

SELECT 'waitSubmit' AS tabFlag, COUNT(DISTINCT srd.id) AS count FROM sample_recipient sr INNER JOIN sample_recipient_detail srd ON sr.id = srd.main_id WHERE sr.is_deleted = FALSE AND approve_status = 'waitSubmit'
${permissionSql}
UNION ALL
SELECT 'approveIng' AS tabFlag, COUNT(DISTINCT srd.id) AS count FROM sample_recipient sr INNER JOIN sample_recipient_detail srd ON sr.id = srd.main_id WHERE sr.is_deleted = FALSE AND approve_status = 'approveIng'
${permissionSql}
UNION ALL
SELECT 'waitOutstock' AS tabFlag, COUNT(DISTINCT srd.id) AS count FROM sample_recipient sr INNER JOIN sample_recipient_detail srd ON sr.id = srd.main_id WHERE sr.is_deleted = FALSE AND sr.approve_status = 'approve' AND srd.exec_status IN ('waitOutstock', 'partOutstock')
${permissionSql}
UNION ALL
SELECT 'completeOutstock' AS tabFlag, COUNT(DISTINCT srd.id) AS count FROM sample_recipient sr INNER JOIN sample_recipient_detail srd ON sr.id = srd.main_id WHERE sr.is_deleted = FALSE AND srd.exec_status = 'completeOutstock'
${permissionSql}
UNION ALL
SELECT 'reject' AS tabFlag, COUNT(DISTINCT srd.id) AS count FROM sample_recipient sr INNER JOIN sample_recipient_detail srd ON sr.id = srd.main_id WHERE sr.is_deleted = FALSE AND approve_status = 'reject'
${permissionSql}
